flow:
/// Lists a page of tickets whose title contains the keyword.
server action GetTicketList
  /// Position of the first ticket of the page.
  in StartIndex: Integer
  /// How many tickets a page has.
  in MaxRecords: Integer
  /// Text the title contains (empty: all).
  in SearchKeyword?: Text
  /// The tickets of the page.
  out List: Ticket List
  /// How many tickets match.
  out Total: Long Integer
  Found = aggregate FROM Ticket WHERE (SearchKeyword = "" or Ticket.Title like "%" + SearchKeyword + "%") SORT Ticket.OpenedOn desc MAX MaxRecords START StartIndex
  assign  # The page and the total
    List = Found.List
    Total = Found.Count
  end
/// Reads one ticket by its identifier.
server action GetTicketById
  /// The ticket to read.
  in TicketId: Ticket Identifier
  /// The ticket.
  out Ticket: Ticket
  Found = aggregate FROM Ticket WHERE (Ticket.Id = TicketId) MAX 1
  assign Ticket = Found.List.Current.Ticket  # The ticket
  end
/// Stores a ticket after its checks.
server action StoreTicket
  /// The ticket to store.
  in Ticket: Ticket
  /// The stored ticket.
  out TicketId: Ticket Identifier
  Saved = CreateOrUpdateTicket(Source=Ticket)
  assign TicketId = Saved.Id  # The identifier
  end
/// Removes a ticket.
server action RemoveTicketById
  /// The ticket to remove.
  in TicketId: Ticket Identifier
  DeleteTicket(Id=TicketId)
  end
